Method.Implementation:
	#dim tSC As %Status=$$$OK
    set tSC=..Adapter.SetAutoCommit(1) 

	$$$TRACE("Inside "_..%ConfigName_" Method ProviderMnemonicLookup")

	set pResponse=##class(IHC.ITF.Response.opDwQueryResponse).%New()
	if (pRequest.npi'=""){
	   try{	
 	      set tSC=..Adapter.ExecuteQuery(.tResult,"SELECT dbo.DN202.MNEMONIC AS DN2_MNEMONIC,dbo.DN3.MNEMONIC AS DN3_MNEMONIC FROM dbo.DN3 (NOLOCK) INNER JOIN dbo.DN202 (NOLOCK) ON dbo.DN3.BILLING_AREAS = dbo.DN202.Record_Number WHERE dbo.DN3.NPI_NUMBER = '"_
 	      pRequest.npi_"' AND dbo.DN3.Inactive_flag = 'N'")
 	      $$$TRACE("  SUCCESS : "_tSC)		 	   	
	   }CATCH err {		
	      $$$LOGERROR( "Error while Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	      set tSC = $$$ERROR( "SQLError:Executing Query "  _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)	    
	   }	
	   $$$TRACE("  STATUS : "_tSC)	

	   $$$TRACE("check tResult(ProcessTouchWorksParientSsn) "_tResult)
	   If tResult.Next() {
          set pResponse.BillingArea =  tResult.GetData(1)     
          set pResponse.Mnemonic =  tResult.GetData(2)  
          set tSC=..addIdsToCache(pRequest.npi, pResponse.Mnemonic, pResponse.BillingArea)  
       } else {
	      set ids=..getIdsFromCache(pRequest.npi)
	      if ids'="" {
	         set pResponse.BillingArea =  $P(ids,",",2)    
             set pResponse.Mnemonic =   $P(ids,",",1) 
	      }
	      else {
             set pResponse.BillingArea =  ""     
             set pResponse.Mnemonic =  ""    
	      } 
	   } 
	}
	else {
	   set tSC = $$$ERROR( "NPI is null.")	    
	}

	$$$TRACE("  MNEMONIC in DW RESPONSE : "_pResponse.Mnemonic)	
	quit tSC

#dim tSC As %Status=$$$OK

$$$TRACE("Inside "_..%ConfigName_" Method addIdsToCache")
set ids = ..getIdsFromCache(pNpi)
if ids'="" {
   &sql(UPDATE IHC_ITF_Operation.ProviderIds SET Mnemonic = :pMnemonic, BillingArea = :pBarea where Npi = :pNpi)
   	$$$TRACE("Update npi: "_pNpi_" Mnemonic: "_pMnemonic_" BillingArea: "_pBarea)
}
else {
   &sql(INSERT INTO  IHC_ITF_Operation.ProviderIds(Npi, Mnemonic, BillingArea) values(:pNpi, :pMnemonic, :pBarea))
   	$$$TRACE("Insert npi: "_pNpi_" Mnemonic: "_pMnemonic_" BillingArea: "_pBarea)
}
quit tSC
